package main

import (
	"fmt"
)

func mod(a, b int) int {
	return (a%b + b) % b
}

func imprimirEstado(lista []int, idxEspada int) {
	fmt.Print("[")
	for i, p := range lista {
		fmt.Print(" ")
		if i == idxEspada {
			if p > 0 {
				fmt.Printf("%d>", p)
			} else {
				fmt.Printf("<%d", p)
			}
		} else {
			fmt.Printf("%d", p)
		}
	}
	fmt.Println(" ]")
}

func main() {
	var n, e, f int
	if _, err := fmt.Scan(&n, &e, &f); err != nil {
		return
	}

	participantes := make([]int, n)
	sinal := f
	for i := 0; i < n; i++ {
		participantes[i] = (i + 1) * sinal
		sinal *= -1
	}

	// Encontra a posição inicial baseada no valor absoluto E
	pos := 0
	for i, v := range participantes {
		if v == e || v == -e {
			pos = i
			break
		}
	}

	for len(participantes) > 1 {
		imprimirEstado(participantes, pos)

		atual := participantes[pos]
		var alvo int

		if atual > 0 {
			alvo = mod(pos+1, len(participantes))
		} else {
			alvo = mod(pos-1, len(participantes))
		}

		// Armazena o valor de quem está com a espada para achá-lo após a remoção
		quemEstaComAEspada := participantes[pos]

		// Remove o alvo
		participantes = append(participantes[:alvo], participantes[alvo+1:]...)

		// Reencontra a posição de quem está com a espada no novo slice
		for i, v := range participantes {
			if v == quemEstaComAEspada {
				pos = i
				break
			}
		}

		// AGORA move a espada para o próximo sobrevivente na direção do ataque
		if atual > 0 {
			pos = mod(pos+1, len(participantes))
		} else {
			pos = mod(pos-1, len(participantes))
		}
	}

	imprimirEstado(participantes, 0)
}
